import{_ as n,a0 as l,w as s,s as u,ao as a,I as o,x as t,a1 as r,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"戴文的Linux內核專題：15 配置內核 (11) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：15 配置內核 (11) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：15 配置內核 (11) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：15 配置內核 (11) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/15 The Linux Kernel--Configuring the Kernel Part 11","title":"戴文的Linux內核專題：15 配置內核 (11)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/15 The Linux Kernel--Configuring the Kernel Part 11.md","filePath":"[post].md"}'),I={name:"The Linux Kernel/15 The Linux Kernel--Configuring the Kernel Part 11.md"};function S(d,e,C,x,L,A){const i=l("Link");return s(),u("div",null,[e[11]||(e[11]=a('<h1 id="戴文的linux內核專題-15-配置內核-11" tabindex="-1">戴文的Linux內核專題：15 配置內核 (11) <a class="header-anchor" href="#戴文的linux內核專題-15-配置內核-11" aria-label="Permalink to “戴文的Linux內核專題：15 配置內核 (11)”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpg.530/" alt=""></p><p>準備好配置更多的驅動了麼？還有很多要做。</p><p>Linux支持兩種不同的康柏智能陣列控制器：(Compaq SMART2 support)和(Compaq Smart Array 5xxx support)。陣列控制器是將物理存儲單元表現為邏輯單元的設備。這些控制可能同樣實現了基於硬件的RAID。硬件和軟件RIAD的不同是簡單的。Linux管理並見到軟件RIAD。Linux將硬件RAID視為另外的存儲單元。這意味着Linux沒有意識到設備就是RAID驅動器。硬件(陣列控制器)獨立於內核管理着RAID系統。這對於系統的性能更好因為內核不必配置或者管理RAID。注意，不同的陣列控制器有不同的RAID能力。</p><p>上面提到的陣列控制器可以通過這個驅動訪問SCSI磁帶(SCSI tape drive support for Smart Array 5xxx)。SCSI磁帶是使用SCSI協議的磁帶機。</p><p>PCI RAID控制器Mylex DAC960、AcceleRAID和eXtremeRAID在這個驅動中支持(Mylex DAC960/DAC1100 PCI RAID Controller support)。PCI RAID控制器是一個連接到PCI卡的陣列控制器。RAID控制器是擁有RAID功能的陣列控制器。</p><p>帶電源備份的MM5415內存芯片在這個驅動中支持(Micro Memory MM5415 Battery Backed RAM support)。帶後備電源內存芯片允許數據在切斷電源後繼續保存在內存設備中。這有助於保護數據。不然，當電源斷開後，當前的計算機會話就會丟失。</p><p>當啓用這個特性後，可以將典型的文件(比如ISO文件)作為一個塊設備並掛載它Loopback device support)。這對於從鏡像文件中檢索文件而不必把文件燒錄到光盤或者解壓出來。想像一下你從因特網上得到了一份包含了很多文件的ISO文件。如果你只需要包中的一個文件並且用户不希望燒寫ISO到光盤上或者不想知道如何打開一個ISO文件。用户可以用掛載ISO來替代。</p><p>Linux內核在初始化階段會創建一些迴路設備，所以一些迴環設備已經準備好並創建了(Number of loop devices to pre-create at init time)。當一個文件(像ISO)或者虛擬設備(就像虛擬磁盤驅動器[vhd])被作為迴環設備掛載時會節約一些時間。這個設定允許開發者選擇內核可以預 創建多少迴環設備。</p><p>當&quot;Cryptoloop Support&quot;啓用後就可以CryptoAPI創建密碼。這個用於硬件驅動器加密。然而，並不是所有的文件系統都支持。</p><p>下面用户可以啓用&quot;DRBD Distributed Replicated Block Device support&quot;(譯註：Linux上的分佈存儲系統)。這個就像網絡RAID1。這些設備擁有設備文件/dev/drbdx。這些設備通常被用於集羣，這裏集羣中的每台計算機都有一個從主單元鏡像過來的存儲單元。這意味着每台計算機的硬盤是位於組中心計算機硬盤的鏡像拷貝。集羣是一組計算機扮演着一台大型強力單元的角色。然而，每個集羣都有一台控制計算機稱為主節點。餘下的計算機是從節點。</p><p>DRBD支持用於測試IO錯誤處理的故障注射(DRBD fault injection)。記住，故障注射就是使設備/軟件認為發生了一個錯誤，因此開發者可以測試硬件/軟件如何處理錯誤</p><p>如果內核要成為網絡塊設備的客户端，那麼啓用這個特性(Network block device support)。第一個設備文件是/dev/nd0。網絡塊設備是通過網絡訪問的遠程存儲單元。</p><p>直接連接SSD到PCI或者PCIe需要這個驅動(NVM Express block device)。</p><p>用這個特性允許將單獨的SCSI OSD(object-based storage,基於對象的存儲)對象作為塊設備(OSD object-as-blkdev support)。</p><p>下一個驅動是&quot;Promise SATA SX8 support&quot;。這個驅動用於Promise公司(Promise Technology Inc.)生產的SATA控制器。</p><p>Linux允許將一部分內存作為塊設備(RAM block device support)。這通常見與完全運行於內存上的Linux的live發行版。Linux的live發行版會卸載光盤並接着加載到內存中，所以在嘗試一個新的操作系統或者修復另一個系統時不會傷害到已安裝的系統。</p><p>下一個選項允許用户輸入&quot;Default number of RAM disks&quot;(默認RAM磁盤數量)。</p><p>&quot;Default RAM disk size&quot;(默認RAM磁盤大小)可以以KB設置大小。</p><p>內核可以支持在內存設備的XIP文件系統作為塊設備(Support XIP filesystems on RAM block device)。這個特性會增大內核的大小。 XIP (eXecute In Place)文件系統是一個允許可執行文件在相同的文件系統上存儲數據而不必像其他應用一樣利用內存。在一個駐留在內存上的live版linux系統上運行可執行文件時需要這個文件系統。</p><p>下面，內核可以支持&quot;Packet writing on CD/DVD media&quot;。(CD/DVD刻錄機支持.)</p><p>內核開發者可以設置最大活躍併發包數量(Free buffers for data gathering)。大的數字會以內存的消耗為代價加速寫入性能。一個包會消耗大約64KB。</p><p>Linux內核可以使用可擦寫光盤作為緩存空間(Enable write caching)。這個特性仍然是試驗性質。</p><p>下面的特性允許通過以太網線纜使用ATA規範(ATA over Ethernet support)。</p><p>下面的驅動允許虛擬塊設備創建為virtio(Virtio block driver)。virtio是IO虛擬化平台。</p><p>一些非常老的硬盤還要一個特殊的驅動(Very old hard disk (MFM/RLL/IDE) driver)。</p><p>這裏有一個驅動用於先前提到的Rados設備(Rados block device (RBD))。</p><p>下面是一個特殊的設備驅動(IBM FlashSystem 70/80 PCIe SSD Device Driver)。</p><p>現在，我們可以進入雜項設備。第一個設定是啓用/禁用電位器(Analog Devices Digital Potentiometers )。</p><p>如果電位器在I2C總線上，那麼就啓用這個(support I2C bus connection)。</p><p>如果電位器是連接到SPI總線，那麼需要這個驅動(support SPI bus connection)。</p><p>注意:Linux內核支持很多傳感器因為Linux內核經常用於天氣設備和機器人。</p><p>這個驅動用於IBM RSA(Condor)服務處理器(Device driver for IBM RSA service processor)。</p><p>內核同樣支持PCI Sensable PHANToM設備驅動(Sensable PHANToM (PCI))。</p><p>這個驅動指引不同來自並行追蹤接口(Parallel Trace Interface (PTI))的追蹤數據發往Intel Penwell PTI口 (Parallel Trace Interface for MIPI P1149.7 cJTAG standard)。這個被指領的數據用於調試目的。</p><p>一些帶有IOC4芯片的SGI IO控制器需要這個驅動(SGI IOC4 Base IO support)。SGI IO是由SCI管理的輸入/輸出設備。IOC4芯片控制着許多由這些設備執行的任務。這是一個基礎驅動。其他對這些設備的驅動依賴於這個驅動。</p><p>這裏有很少的TI閃存媒體適配器驅動在Linux內核中，(TI Flash Media interface support) 和(TI Flash Media PCI74xx/PCI76xx host adapter support)。</p><p>這個驅動(&quot;Integrated Circuits ICS932S401&quot;)用於ICS932S401時鐘控制芯片。</p><p>Atmel同步串行通信外設(Synchronized Serial Communication peripheral (SSC))有一個驅動在內核中(Device driver for Atmel SSC peripheral)。這個設備提供點對點的設備間的串行連接。</p><p>&quot;Enclosure Services&quot;特性支持硬盤托架。</p><p>這是對於CS5535/CS5536芯片的定時器驅動(CS5535/CS5536 Geode Multi-Function General Purpose Timer (MFGPT) support)。</p><p>這個驅動讓應用可以與HP工業標準服務器中的iLO管理處理器通信(Channel interface driver for the HP iLO processor)。&quot;iLO&quot;代表的是&quot;Integrity Integrated Lights-Out&quot;.iLO允許遠程服務器管理。</p><p>Linux內核支持ALS APDS9802光敏傳感器(Medfield Avago APDS9802 ALS Sensor module)。一些其他支持的傳感器包括：</p><ul><li>Intersil ISL29003 ambient light sensor</li><li>Intersil ISL29020 ambient light sensor</li><li>Taos TSL2550 ambient light sensor</li><li>ROHM BH1780GLI ambient light sensor</li><li>BH1770GLC / SFH7770 combined ALS - Proximity sensor</li><li>APDS990X combined als and proximity sensors</li></ul><p>注意：如果內核是為廣泛的計算機編譯的話，大多數驅動應該以模組形式加入。</p><p>Linux甚至可以使用&quot;Honeywell HMC6352 compass&quot;(一種電子羅盤)。</p><p>內核同樣支持&quot;Dallas DS1682 Total Elapsed Time Recorder with Alarm&quot;。(一種運行時間記錄儀)</p><p>16位的數模轉換器通過這個驅動支持(Texas Instruments DAC7512)。</p><p>&quot;VMware Balloon Driver&quot;將客户機操作系統不需要的物理內存頁交給需要那些需要的。</p><p>這裏有兩個不同的壓力傳感器(BMP085 digital pressure sensor on I2C) 和 (BMP085 digital pressure sensor on SPI)。</p><p>Intel輸入/輸出集線器(Intel Input/Output Hub (IOH))同樣在內核中支持(Intel EG20T PCH/LAPIS Semicon IOH(ML7213/ML7223/ML7831) PHUB)。具體地説，這個是Intel Topcliff芯片組的PCH PHUB(Platform Controller Hub Packet Hub)</p><p>&quot;FSA9480 USB Switch&quot;是檢測設備何時插入的檢測器。</p><p>下一個選項允許比特流配置(Lattice ECP3 FPGA bitstream configuration via SPI)。</p><p>Silicon微控制器使用Silicon實驗室C2端口，這需要一個特殊的驅動(Silicon Labs C2 port support)。</p><p>再説一次，繼續留意下一篇文章因為我們還有更多的要做。</p><hr>',56)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),r(i,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-11.4640/"},{default:p(()=>[...e[0]||(e[0]=[t("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-11.4640/",-1)])]),_:1})]),o("p",null,[e[4]||(e[4]=t("譯者：",-1)),r(i,{href:"https://github.com/geekpi"},{default:p(()=>[...e[2]||(e[2]=[t("geekpi",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),r(i,{href:"https://github.com/wxy"},{default:p(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[8]||(e[8]=t("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),r(i,{href:"http://linux.cn/"},{default:p(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const c=n(I,[["render",S]]);export{D as __pageData,c as default};
